pub fn score_bin(
    _item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised stream progress
    let progress = step_index as f64 / total_items as f64;

    // Residual after placing the item
    let r = post_residual as f64;

    // Auxiliary values
    let o = open_bins_count as f64;
    let f = fitting_bins_count as f64;
    let m = mean_residual;
    let n = next_item_size as f64;

    // Non‑linear polynomial coupling with progress
    let early_term = (1.0 - progress).powi(3) * r * 0.4;
    let late_term = progress.powi(2) * r * 0.2;

    // Penalise many open bins (encourage consolidation)
    let open_bins_term =
        ((o / (total_items as f64 + 1.0)).powi(2)) * r * 0.15;

    // Prefer residual close to the mean
    let mean_term = -((r - m).abs() * 0.1);

    // Penalise bins that are not the last fitting option
    let fitting_penalty = (f - 1.0).max(0.0) * 5.0;

    // New‑bin penalty (if there are already open bins)
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            (open_bins_count as f64).ln() * 2.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Lookahead penalty: next item would not fit into the residual
    let lookahead_penalty = if next_item_size > 0 && n > r {
        (n - r) * 5.0
    } else {
        0.0
    };

    // Combine all terms
    let score = r
        + early_term
        + late_term
        + open_bins_term
        + mean_term
        + fitting_penalty
        + new_bin_penalty
        + lookahead_penalty;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress
    let progress = step_index as f64 / total_items as f64;
    // Residual after placement
    let residual_after = post_residual as f64;
    // Ratio of current residual to bin capacity
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    // Difference from the mean residual
    let mean_diff = (residual_after - mean_residual).abs();

    // Base score: raw residual
    let mut score = residual_after;

    // Compaction drive – tighter early, looser later
    let early_weight = (1.0 - progress).powf(3.0);
    let late_weight = progress.powf(2.0);
    let compaction = early_weight * residual_after * 0.25
        + late_weight * residual_after * 0.08;
    score += compaction;

    // Open‑bin congestion penalty – quadratic scaling
    let open_bins = open_bins_count as f64;
    let open_penalty = ((open_bins / (total_items as f64 + 1.0)).powi(2))
        * residual_after
        * 0.07;
    score += open_penalty;

    // Encourage residuals near the mean – stronger penalty
    score -= mean_diff * 0.12;

    // Fitting options penalty: fewer alternatives preferred
    let fitting_penalty = (fitting_bins_count as f64 - 1.0).max(0.0) * 2.5;
    score += fitting_penalty;

    // New‑bin bias: penalise opening a new bin when many are already open
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let new_bin_bias = (open_bins_count as f64).ln().max(0.1) * 1.2;
            score += new_bin_bias;
        }
    }

    // Look‑ahead: discourage placing large items in bins that can't hold the next one
    if next_item_size > residual_after as u32 {
        let lookahead = (next_item_size - residual_after as u32) as f64 * 3.0;
        let damp = 1.0 - progress.powi(2);
        score += lookahead * damp;
    }

    // Size‑ratio bonus for medium‑sized items
    if item_size > (bin_capacity / 4) && item_size < (bin_capacity * 3 / 4) {
        let mid_bonus = residual_ratio * 0.05;
        score -= mid_bonus;
    }

    // Tight‑fit bonus when residual is very small but remaining residual is large
    if bin_residual < (bin_capacity / 10) && residual_after > mean_residual {
        score -= 1.0;
    }

    // Reward almost empty bins when overall waste is low
    if residual_after < 3.0 {
        score -= 0.7;
    } else if residual_after > 25.0 {
        score += 0.6;
    }

    // Encourage bins whose residual ratio is close to the mean residual ratio
    let mean_ratio = mean_residual / bin_capacity as f64;
    let ratio_diff = (residual_ratio - mean_ratio).abs();
    if ratio_diff < 0.015 {
        score -= 0.25;
    }

    // Item‑size fraction adjustment – large items waste more, small items fit better
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.8 {
        score += 0.6; // large item, penalise
    } else if item_frac < 0.2 {
        score -= 0.3; // small item, reward
    }

    score
}

