pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress and residual values
    let progress = step_index as f64 / total_items as f64;
    let residual_after = post_residual as f64;
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let next_item = next_item_size as f64;
    let mean_residual = mean_residual.max(1e-6);

    // Base score: raw residual (larger residual is worse)
    let mut score = residual_after;

    // Early‑phase compaction push: tighter fit early
    let early_term = (1.0 - progress).powi(3) * residual_after * 0.40;
    // Late‑phase relaxation: allow looser fits later
    let late_term = progress.powi(2) * residual_after * 0.15;
    score += early_term + late_term;

    // Congestion penalty: more open bins → higher cost
    let open_bins = open_bins_count as f64;
    let congestion = (open_bins / (total_items as f64 + 1.0))
        .powi(3)
        * residual_after
        * 0.10;
    score += congestion;

    // Mean‑residual coupling: reward residuals close to the mean
    let diff = (residual_after - mean_residual).abs();
    let sigma = 0.03_f64; // tuning width
    let gaussian = (-diff * diff / (2.0 * sigma * sigma)).exp();
    score -= gaussian * 3.0;

    // Fitting alternatives penalty: prefer bins with fewer choices
    let fitting_penalty = ((fitting_bins_count as f64) - 1.0).max(0.0) * 3.5;
    score += fitting_penalty;

    // New‑bin bias: penalise opening a new bin when many are already open
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let bias = (open_bins_count as f64).sqrt() * 1.20;
            score += bias;
        }
    }

    // Look‑ahead: discourage placing large items in bins that cannot hold the next one
    if next_item > residual_after {
        let lookahead = (next_item - residual_after) * 4.0;
        score += lookahead;
    } else {
        // Bonus for leaving enough space for the next item
        score -= 2.0;
    }

    // Size‑ratio coupling: large items benefit from higher residual ratios
    if item_size > (bin_capacity / 2) {
        score -= residual_ratio * 0.08;
    }

    // Small‑item penalty for leaving too much residual space
    if item_size <= (bin_capacity / 4) && residual_ratio > 0.60 {
        score += (residual_ratio - 0.60) * 2.0;
    }

    // Global open‑bin threshold: discourage using bins when many are open
    if open_bins_count > 10 {
        score += 1.0;
    }

    score
