        score -= 12.0 * (1.0 - t);
    }

    // 4. Tight‑fit encouragement
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let tightness = 1.0 - residual_ratio; // 0.0 .. 1.0
    score -= tightness * 15.0 * t.powf(1.5);

    // 5. Existing‑bin pressure
    score += (open_bins_count as f64) * t.powi(2);

    // 6. New‑bin penalty early, softened near end
    if bin_residual == bin_capacity {
        let new_bin_penalty = 25.0 * (1.0 - t).powi(2);
        score += new_bin_penalty;
    }

    // 7. Size‑dependent penalty for large items early
    let size_factor = (item_size as f64) / bin_capacity as f64;
    score += size_factor.powi(3) * (1.0 - t).powi(3);

    // 8. Lookahead bonus if the next item will also fit
    if next_item_size <= post_residual {
        let future_residual = post_residual - next_item_size;
        let future_tightness =
            1.0 - (future_residual as f64 / bin_capacity as f64);
        score -= future_tightness * 8.0 * (1.0 - t);
    }

    // 9. Penalize excessive bin count when residuals are high
    if open_bins_count > 5 && mean_residual > (bin_capacity as f64) * 0.3 {
        score += 5.0;
    }

    score
}

