    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Fraction of the stream processed
    let progress = step_index as f64 / total_items as f64;

    // Ratio of residual after placement to capacity
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Base score: tighter fits get a lower score
    let mut score = 2.0 * residual_ratio.powi(2);

    // Penalise deviation from global mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev / mean_residual.max(1.0);

    // Extra penalty for bins that were already highly full
    if bin_residual > (bin_capacity * 8 / 10) {
        score += 1.5
            * ((bin_residual - (bin_capacity * 8 / 10)) as f64 / bin_capacity as f64);
    }

    // Look‑ahead: reward bins that can also accommodate the next item
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 1.0 * next_item_size as f64;
        } else {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
            if next_item_size > post_residual * 3 / 2 {
                score += 0.3 * (next_item_size as f64 - (post_residual as f64 * 1.5));
            }
        }
    }

    // Prefer existing bins when many are open
    score -= 0.02 * (open_bins_count as f64).powf(0.9);

    // New‑bin decision: more forgiving later in the stream
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count <= 2 {
            9.0
        } else if fitting_bins_count <= 5 {
            6.0
        } else {
            4.0
        };
        score += base
            * (1.0 - progress).powi(2)
            * (1.0 + 0.1 * (open_bins_count as f64).sqrt());
    }

    // Huge bonus if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Tighten the fit: bonus when the final residual is close to the mean
    if (post_residual as f64 - mean_residual).abs() <= 0.04 * bin_capacity as f64 {
        score -= 2.0;
    }

    // Small bonus for almost full bins
    if residual_ratio < 0.08 {
        score -= 0.5;
    }

    // Extra penalty if residual is very small (dead space)
    if residual_ratio < 0.01 {
        score += 0.6;
    }

    // Penalise too many open bins late in the stream
    if open_bins_count > 12 && progress > 0.6 {
        score += 1.2;
    }

    // Scale with the square‑root of fitting bin count to smooth large jumps
    score * (1.0 + 0.08 * (fitting_bins_count as f64).sqrt())
}

