    }

    // Look‑ahead: next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Can also fit the next item – reward
            score -= 0.6 * next_item_size as f64;
        } else {
            // Next item will overflow – penalize
            score += 1.2 * (next_item_size - post_residual) as f64;
        }
