    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized progress
    let t = step_index as f64 / total_items as f64;

    // Residual ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;

    // Base score: residual amount
    let mut score = post_residual as f64;

    // 1. Penalize deviation from mean residual
    let diff = (residual_ratio - mean_ratio).abs();
    score += diff.powf(1.4) * (1.0 - t);

    // 2. Bonus for small residual (encourages compactness)
    score -= (1.0 - residual_ratio).powi(2) * 8.0 * (1.0 - t);

    // 3. Penalty if next item cannot fit in the same bin
    let need = if next_item_size > post_residual {
        (next_item_size - post_residual) as f64
    } else {
        0.0
    };
    score += need.powi(2) * (1.0 - t).powi(2);

    // 4. Extra bonus if this is the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t);
    }

    // 5. Prefer existing bins as the stream progresses
    let open_log = if open_bins_count > 0 {
        (open_bins_count as f64).ln()
    } else {
        0.0
    };
    score += open_log * t.powi(2) * 0.6;

    // 6. New‑bin penalty early in the stream
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t);
    }

    // 7. Size‑dependent smooth penalty for large items
    let size_factor = item_size as f64 / bin_capacity as f64;
    score += size_factor.powi(2) * (1.0 - t).powi(2);

    // 8. Penalty for having many fitting bins (encourages tighter packing)
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).sqrt() * (1.0 - t) * 0.4;
    }

    score
}

pub fn score_bin(
