pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // 1. Quadratic waste penalty – discourage large gaps
    score += (post_residual as f64).powi(2) * 0.00012;

    // 2. Tight‑fit bonus – reward bins that leave very little space
    if post_residual <= 3 {
        score -= 2.0;
    } else if post_residual <= 4 {
        score -= 1.5;
    }

    // 3. Residual proximity to mean – encourage balanced packing
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score -= residual_diff * 0.06;

    // 4. Target‑size bias when many bins are open
    if open_bins_count > 5 {
        let target = bin_capacity as f64 * 0.45;
        let target_diff = (bin_residual as f64 - target).abs();
        score -= target_diff * 0.025;
    } else if open_bins_count > 4 {
        let target = bin_capacity as f64 * 0.48;
        let target_diff = (bin_residual as f64 - target).abs();
        score -= target_diff * 0.022;
    }

    // 5. Last‑fit bonus – avoid leaving a single fitting bin unused
    if fitting_bins_count == 1 {
        score -= 4.5;
    }

    // 6. Next‑item feasibility penalty
    if next_item_size > 0 && post_residual < next_item_size {
        if step_index > total_items * 3 / 4 {
            score += 15.0;
        } else {
            score += 10.0;
        }
    }

    // 7. Progress‑aware penalty – the later we are, the more we penalize waste
    let fraction = step_index as f64 / total_items as f64;
    score -= fraction * 1.8;

    // 8. Multiple‑of‑10 bonus – slightly favor clean cuts
    if bin_residual % 10 == 0 {
        score -= 1.5;
    }

    // 9. New‑bin avoidance – penalize opening an empty bin when other bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0;
    }

    // 10. Near‑full bin penalty – discourage opening a new bin when the current one is almost full
    if bin_residual <= 3 && bin_residual < bin_capacity {
        score += 3.0;
    }

    // 11. Small residual bonus – reward bins that are almost empty but still fit the item
    if post_residual < 6 && bin_residual > 0 {
        score -= 0.6;
    }

    // 12. Dead‑space ratio penalty – discourage bins with excessive unused capacity
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_ratio > 0.35 {
        score += 1.0;
    } else if dead_ratio > 0.20 {
        score += 0.4;
    }

    // 13. Excessive open‑bin penalty – discourage opening new bins when many are already open
    if open_bins_count > 7 && bin_residual == bin_capacity {
        score += 1.5;
    }

    // 14. Multiple‑fit penalty – if many bins can fit and the residual is not tight, add a small cost
    if fitting_bins_count > 5 && post_residual > 4 {
        score += 0.6;
    }

    // 15. Near‑full residual bonus – small reward for bins that leave very little space
    if bin_residual < bin_capacity * 2 / 5 {
        score -= 0.4;
    }

    // 16. Excess slack after placing the item – penalize if we leave too much unused space for next item
    if post_residual >= next_item_size + 3 {
        score += 0.4;
    }

    // 17. Large residual relative to mean when many bins fit – slight discouragement
    if bin_residual > (mean_residual as u32 + 15) && fitting_bins_count > 2 {
        score += 0.8;
    }

    // 18. Many open bins and high residual – penalize to encourage filling existing bins
    if open_bins_count > 10 && bin_residual as f64 > mean_residual {
        score += 0.8;
    }

    // 19. Final item special case – if we are at the last item, penalize any leftover space
    if step_index == total_items - 1 && post_residual > 0 {
        score += 1.5;
    }

    // 20. Tight‑fit reward for near‑empty bins – extra incentive for almost empty bins
    if post_residual <= 1 {
        score -= 2.0;
    }

    // 21. Almost full bin penalty – discourage opening a new bin when the current one is near capacity
    if bin_residual >= bin_capacity - 4 && bin_residual < bin_capacity {
        score += 0.5;
    }

    // 22. Late‑stage open‑bin penalty – slight cost when many bins are open late in the stream
    if step_index > total_items * 2 / 3 && open_bins_count > 6 {
        score += 0.3;
    }

    // 23. Many open bins with low waste – slight penalty for low residuals when many bins fit
    if fitting_bins_count > 8 && post_residual < 8 {
        score += 0.2;
    }

    score
}

pub fn score_bin(
