    // ------------------------------------------------------------------
    if post_residual <= 1 {
        score += 3000.0;
    } else if post_residual <= 3 {
        score += 1500.0;
    } else if post_residual <= 5 {
        score += 700.0;
    } else if post_residual <= 10 {
        score += 200.0;
    } else {
        score += 20.0;
    }

    // ------------------------------------------------------------------
    // Residual ratio penalty / reward
    // ------------------------------------------------------------------
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    let ratio_penalty = if res_ratio > 0.35 {
        let excess = (res_ratio - 0.35) / 0.65;
        excess.powi(2) * 1600.0
    } else {
        0.0
    };
    if step_index < total_items / 2 {
        score += ratio_penalty;
    } else {
        score += ratio_penalty * 0.2;
    }

    // ------------------------------------------------------------------
    // Mean‑residual proximity
    // ------------------------------------------------------------------
    let diff_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_mean * 1.2;

    // ------------------------------------------------------------------
    // Open‑bin cost
    // ------------------------------------------------------------------
    let open_cost = (open_bins_count as f64).ln() * 1.6;
    score += open_cost;
    if open_bins_count > 300 {
        score += 800.0;
    }

    // ------------------------------------------------------------------
    // New‑bin candidate logic
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.90 {
            // Very large item – favor a fresh bin
            score -= 50.0;
        } else if fitting_bins_count > 0 {
            // Prefer existing bins but still allow new if necessary
            score -= 30.0;
        } else {
            // No fitting bins – must open
            score += 20.0;
        }
    }

    // ------------------------------------------------------------------
    // Look‑ahead: next item fit assessment
    // ------------------------------------------------------------------
    if next_item_size > 0 {
        let residual_after = post_residual as i32;
        let gap = next_item_size as i32 - residual_after;
        if gap > 0 {
            // Next item would not fit – penalty
            let gap_pen = (gap as f64 / bin_capacity as f64) * 250.0;
            score += gap_pen;
        } else {
            // Next item fits – small reward
            let slack = -gap as f64;
            score -= slack / bin_capacity as f64 * 3.0;
        }
    }

    // ------------------------------------------------------------------
    // Reward a unique fitting bin
    // ------------------------------------------------------------------
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // ------------------------------------------------------------------
    // End‑of‑stream tightening
    // ------------------------------------------------------------------
    if step_index > total_items * 3 / 4 && post_residual > mean_residual as u32 {
        score += 25.0;
    }
    if step_index > total_items * 9 / 10 && post_residual > mean_residual as u32 {
        score += 40.0;
    }

    // ------------------------------------------------------------------
    // Periodic diversification bonus
    // ------------------------------------------------------------------
    if step_index % 13 == 0 {
        score -= 3.0;
    }

    // ------------------------------------------------------------------
    // Penalise many fitting bins – encourage consolidation
    // ------------------------------------------------------------------
    if fitting_bins_count > 5 {
        score += (fitting_bins_count as f64 - 4.0) * 5.0;
    }

    // ------------------------------------------------------------------
    // Heavy penalty for too many open bins
    // ------------------------------------------------------------------
    if open_bins_count > 260 {
        score += 700.0;
    }

    // ------------------------------------------------------------------
    // Extra penalty for mismatched pre/post residuals
    // ------------------------------------------------------------------
    if bin_residual < 5 && post_residual > 10 {
        score += 30.0;
    }
    if post_residual <= 2 {
        score -= 10.0;
    }

    score
}

