        if gap > gap_thresh {
            ((gap - gap_thresh) / cap_f).powi(2) * 0.2
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 7️⃣ New‑bin decision – penalise opening when many bins exist and many items remain
    let new_bin = if bin_residual == bin_capacity {
        let open_factor = ((open_bins_count as f64).ln() + 1.0)
            / ((open_bins_count as f64) + 2.0).ln();
        let remaining = (total_items - step_index) as f64 / total_items as f64;
        let mean_factor = 1.0 - (mean_residual / cap_f).min(1.0);
        3.8 * open_factor * remaining.powi(2) * mean_factor
    } else {
        0.0
    };

    // 8️⃣ Fitting bias – favour bins that are common fit options
    let fitting_bias = -0.4 + (fitting_bins_count as f64).sqrt() * 0.05;

    // 9️⃣ Perfect‑fit bonus
    let perfect = if res_f == 0.0 { -3.5 } else { 0.0 };

    // 🔟 Dead‑space penalty – avoid bins that will leave > 3× next item unused
    let dead = if next_item_size > 0 && res_f > next_item_size as f64 * 3.0 {
        ((res_f - next_item_size as f64 * 3.0) / cap_f).powi(2) * 0.45
    } else {
        0.0
    };

    // 1️⃣1️⃣ Small residual bonus – reuse almost‑full bins
    let small = if res_f > 0.0 && res_f < cap_f * 0.04 { -0.6 } else { 0.0 };

    // 1️⃣2️⃣ Ratio penalty – residual too large relative to next item
    let ratio_penalty = if next_item_size > 0 {
        let r = res_f / next_item_size as f64;
        if r > 2.0 {
            (r - 2.0).powi(2) * 0.25
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣3️⃣ Item‑size vs residual penalty
    let item_res_penalty = if item_size > 0 && res_f > 0.0 {
        let r = item_size as f64 / res_f;
        if r > 1.5 {
            (r - 1.5).powi(2) * 0.15
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣4️⃣ Open‑bin linear factor – discourage too many bins
    let open_factor = if open_bins_count > 25 {
        0.04 * open_bins_count as f64
    } else {
        0.0
    };

    // 1️⃣5️⃣ Entropy factor – combine open count and mean residual
    let entropy_factor = ((open_bins_count as f64).ln() + 1.0)
        * (1.0 - (mean_residual / cap_f).min(1.0))
        * 0.1;

    base
        + fullness
        + dev
        + res_item
        + lookahead
        + gap_penalty
        + new_bin
        + fitting_bias
        + perfect
        + dead
        + small
        + ratio_penalty
        + item_res_penalty
        + open_factor
        + entropy_factor
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base cost grows logarithmically with the residual after placement.
    let base = (post_residual as f64 + 1.0).ln() * 1.0;

    // Fullness penalty: we prefer bins that are as full as possible.
    let fullness_penalty = (post_residual as f64 / bin_capacity as f64).powi(3) * 8.0;

    // Deviation from the mean residual to keep the distribution tight.
    let dev = ((post_residual as f64) - mean_residual).powi(2) * 0.2;

    // Lookahead penalty: if the next item does not fit, we prefer a bin
    // that leaves enough space for it.
    let next_gap = if next_item_size > post_residual {
        ((next_item_size as f64 - post_residual as f64).powi(2)) * 0.6
    } else {
        0.0
    };

    // New‑bin bias: discourage opening a new bin when many are already open
    // or when the average residual is already low.
    let mut new_bin_penalty = 0.0;
    if bin_residual == bin_capacity {
        // More open bins increase the penalty, but we temper it with a square‑root.
        let open_factor = (open_bins_count as f64).sqrt() * 0.5;
        let mean_factor = if mean_residual < (bin_capacity as f64 * 0.2) {
            2.0
        } else {
            1.0
        };
        new_bin_penalty = 5.0 + open_factor - mean_factor;

        // Favor new bins earlier in the stream.
        if step_index < total_items / 4 {
            new_bin_penalty *= 0.8;
        }
        // Reduce the penalty slightly in the second half of the stream.
        if step_index > total_items / 3 {
            new_bin_penalty *= 0.7;
        }
    }

    // Fitting bias: if many bins can fit the item, prefer the one that
    // leaves the least residual after placement.
    let fitting_bias = if fitting_bins_count > 1 { -0.3 } else { 0.2 };

    // Perfect‑fit bonus: zero residual after placement.
    let perfect_fit_bonus = if post_residual == 0 { -2.0 } else { 0.0 };

    // Dead‑space penalty: discourage leaving a large fraction of the bin unused.
    let dead_space_penalty = (post_residual as f64 / bin_capacity as f64).powi(2) * 4.0;

    // Size‑ratio penalty: heavily penalise leaving too much space relative
    // to the item size itself.
    let size_ratio_penalty =
        ((post_residual as f64) / (item_size as f64 + 1.0)).powi(2) * 0.4;

    base
        + fullness_penalty
        + dev
        + next_gap
        + new_bin_penalty
        + fitting_bias
        + perfect_fit_bonus
        + dead_space_penalty
        + size_ratio_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
