    let post_f = post_residual as f64;
    let res_f = bin_residual as f64;
    let res_frac = post_f / cap_f;

    // 1️⃣ Base cost – log‑scaled residual
    let base = (post_f + 1.0).ln();

    // 2️⃣ Usage pressure – favour highly utilised bins
    let usage = (1.0 - res_frac).powi(3) * 5.0;

    // 3️⃣ Deviation from mean residual
    let dev = ((post_f - mean_residual).abs() / cap_f).powi(2) * 0.4;

    // 4️⃣ Fit‑proximity bonus – reward bins that leave very little space after placement
    let fit_bonus = if bin_residual >= item_size {
        let after = bin_residual - item_size;
        if after as f64 <= cap_f * 0.05 {
            -0.3
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 5️⃣ Lookahead dead‑space penalty (two‑step lookahead)
    let lookahead = if next_item_size > 0 && post_f >= next_item_size as f64 {
        let new_res = post_f - next_item_size as f64;
        let thresh = cap_f * 0.12;
        if new_res > thresh {
            ((new_res - thresh) / cap_f).powi(2) * 0.28
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 6️⃣ New‑bin decision – weighted by remaining items and mean residual
    let new_bin = if bin_residual == bin_capacity {
        let open_factor = ((open_bins_count as f64 + 1.0).ln()
            / (open_bins_count as f64 + 2.0).ln());
        let remaining_ratio =
            (total_items - step_index) as f64 / total_items as f64;
        let mean_factor = 1.0 - (mean_residual / cap_f).min(1.0);
        4.0 * open_factor * remaining_ratio.powi(2) * mean_factor
    } else {
        0.0
    };

    // 7️⃣ Fitting bias – encourage bins with moderate alternatives
    let fitting_bias = if fitting_bins_count > 12 {
        -0.5
    } else if fitting_bins_count > 6 {
        -0.2
    } else {
        0.1
    };

    // 8️⃣ Perfect‑fit bonus
    let perfect = if post_f == 0.0 { -4.0 } else { 0.0 };

    // 9️⃣ Dead‑space penalty – avoid bins that will leave > 2× next item unused
    let dead = if next_item_size > 0 && post_f > next_item_size as f64 * 2.0 {
        ((post_f - next_item_size as f64 * 2.0) / cap_f).powi(2) * 0.35
    } else {
        0.0
    };

    // 🔟 Small residual bonus – reuse almost‑full bins
    let small = if post_f > 0.0 && post_f < cap_f * 0.05 { -0.6 } else { 0.0 };

    // 1️⃣1️⃣ Residual vs next‑item ratio penalty
    let ratio_penalty = if next_item_size > 0 {
        let r = post_f / next_item_size as f64;
        if r > 1.8 {
            (r - 1.8).powi(2) * 0.22
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣2️⃣ Item size relative to residual penalty
    let item_res_penalty = if item_size > 0 && post_f > 0.0 {
        let r = item_size as f64 / post_f;
        if r > 1.4 {
            (r - 1.4).powi(2) * 0.18
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣3️⃣ Open‑bin count linear factor – discourage too many bins
    let open_factor = if open_bins_count > 25 {
        0.04 * open_bins_count as f64
    } else {
        0.0
    };

