    if open_bins_count > open_limit {
        score += 0.3 * ((open_bins_count as f64 - open_limit as f64).ln());
    }

    // ------------------------------------------------------------------
    // Ratio‑based deviation from mean residual ratio – penalise bins
    // whose residual ratio deviates from the average ratio.
    // ------------------------------------------------------------------
    let mean_ratio = mean_residual / bin_capacity as f64;
    let ratio_dev = (residual_ratio - mean_ratio).abs();
    score += ratio_dev * 7.0;

    // ------------------------------------------------------------------
    // Optional synergy reward – if the bin has more residual before
    // packing than after, and the residual ratio is small, reward it.
    // ------------------------------------------------------------------
    if bin_residual > post_residual && residual_ratio < 0.3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = 0.0;

    // Residual space penalty – prefer tighter gaps but heavily penalize waste
    score += (post_residual as f64).sqrt() * 1.2;
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;
    if post_residual > 0 {
        score += (post_residual as f64).ln() * 2.0;
    }

    // Look‑ahead: assess how the next item would fit after this placement
    if next_item_size > 0 {
        let gap = post_residual as i32 - next_item_size as i32;
        if gap >= 0 {
            if gap < 5 {
                score -= 4.0;          // perfect fit
            } else if gap < 10 {
                score -= 1.0;          // still good
            } else {
                score += (gap as f64) * 0.3; // loose fit
            }
        } else {
            score += (-gap as f64) * 1.2; // next item would overflow
        }
    }

    // New bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count > 2 {
            score += 8.0; // discourage new bin when many options exist
        } else if item_size > bin_capacity / 2 {
            score -= 2.0; // encourage new bin for large items
        }
    }

    // Pressure to keep open bins low
    score += (open_bins_count as f64) * 0.25;

    // Single‑fit penalty
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 12.0;
    }

    // Progress‑dependent penalty – stricter near the end
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.2;
    } else {
        score += progress.powi(2) * post_residual as f64 * 0.1;
    }

    // Deviation from mean residual
    score += (mean_residual - post_residual as f64).abs() * 0.04;

    // Additional look‑ahead penalties
    if next_item_size > 0 && next_item_size < post_residual / 4 {
        score += 5.0;
    }
    if next_item_size > 2 * post_residual {
        score += 3.0;
    }

    // Favor bins that accept large items early
    if item_size as f64 / bin_capacity as f64 > 0.7 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(
