        score += 3.0;
    }

    // ---------- Reward tight packing at the end of the stream ----------
    if next_item_size == 0 && post_residual < 8 {
        score -= 1.0;
    }
    if next_item_size == 0 && post_residual == 0 {
        score -= 0.5;
    }

    // ---------- Reward when residual close to mean ----------
    if (post_residual as f64 - mean_residual).abs() < 2.0 {
        score -= 0.5;
    }

    // ---------- Reward bins below mean residual ----------
    if post_residual as f64 <= mean_residual {
        score -= 0.3;
    } else {
        score += 0.2 * ((post_residual as f64 - mean_residual) / mean_residual);
    }

    // ---------- Penalize excessive slack when many bins fit ----------
    if fitting_bins_count > 5 && post_residual as f64 > mean_residual + 10.0 {
        score += 5.0;
    }

    // ---------- Penalize bins that had too little slack for next item ----------
    if next_item_size > 0 && bin_residual > next_item_size * 2 {
        score += 1.0;
    }

    score
}

